            var untracked = try runGit(allocator, git_path, top_level_dir, (&ls_files_args));
            _ = &untracked;
            defer {
            _ = untracked.stdout.deinit();
            }
            defer {
            _ = untracked.stderr.deinit();
            }
            if (untracked.spawn_failed) {
                return error.GitFailed;
            }
            if (untracked.ok) {
                _ = appendPaths(set, git_root, untracked.stdout.items);
            }
        }
        return set;
}

pub fn runGit(allocator: std.mem.Allocator, git_path: []const u8, cwd: []const u8, args: []const []const u8) std.mem.Allocator.Error!GitResult {
        var argv = try std.array_list.Managed(PathSlice).initCapacity(allocator, (args.len + 3));
        _ = &argv;
        defer {
        _ = argv.deinit();
        }
        _ = argv.appendAssumeCapacity(git_path);
        _ = argv.appendAssumeCapacity("-c");
        _ = argv.appendAssumeCapacity("core.quotePath=off");
        _ = argv.appendSliceAssumeCapacity(args);
        const proc = (blk_catch_4: { break :blk_catch_4 ((bun.spawnSync((&.{ .argv = argv.items, .cwd = cwd, .stdout = .buffer, .stderr = .buffer, .stdin = .ignore, .envp = null, .windows = (if (Environment.isWindows) .{ .loop = jsc.EventLoopHandle.init(jsc.VirtualMachine.get()) } else null) }))) catch |e| { _ = &e; _ = Output.errGeneric("--changed: failed to spawn git: {s}", .{ @errorName(e) });
        return GitResult{ .ok = false, .spawn_failed = true, .stdout = .init(allocator), .stderr = .init(allocator) }; }); });
        return (switch (proc) {
.err => |e| {
{
            _ = Output.errGeneric("--changed: failed to spawn git: {f}", .{ e });
            return GitResult{ .ok = false, .spawn_failed = true, .stdout = .init(allocator), .stderr = .init(allocator) };
        }
},
.result => |res| GitResult{ .ok = res.isOK(), .stdout = res.stdout, .stderr = res.stderr },
});
}

pub fn appendPaths(set: *bun.StringSet, git_root: []const u8, stdout: []const u8) void {
        var buf: bun.PathBuffer = undefined;
        _ = &buf;
        var it = std.mem.tokenizeAny(u8, stdout, "\r\n");
        _ = &it;
        while (it.next()) |line| {
            const rel = strings.trim(line, " \t");
            if ((rel.len == 0)) {
                continue;
            }
            const rel_slice: [1][]const u8 = .{ rel };
            const abs = bun.path.joinAbsStringBuf(git_root, (&buf), (&rel_slice), .auto);
            if ((!bun.sys.exists(abs))) {
                continue;
            }
            _ = bun.handleOom(set.insert(abs));
        }
}
